cards.icon:
[[[
const isDoorOpen = function(st, invert) {
  if (!st) return null;
  const s = String(st.state == null ? '' : st.state).toLowerCase();
  if (!s || ['unavailable','unknown','none'].indexOf(s) >= 0) return null;
  const openish = ['on', 'open', 'opened', 'detected', 'true'];
  const closedish = ['off', 'closed', 'close', 'clear', 'false', 'undetected'];
  if (openish.indexOf(s) >= 0) return invert ? false : true;
  if (closedish.indexOf(s) >= 0) return invert ? true : false;
  return false;
};
  const id = (variables && variables.sensor_id)
    || (entity && entity.entity_id);
  const st = (id && states && states[id]) ? states[id] : entity;
  const open = isDoorOpen(st, false);
  if (open === true) return 'mdi:garage-open';
  if (open === false) return 'mdi:garage';
  return 'mdi:garage';
]]]

